// =============================================================================
// NOVA ATELIER — "Premium Pricing Card" (hub-home visual-stage child)
// 1) COMPOSITION: dark graded backdrop plane behind a machined 3D card slab
//    (2.4 x 3.2 x depth) centered at origin; header strip across top, tier
//    name -> price+caption -> 4 feature rows w/ hairlines -> CTA button near
//    bottom; a thin foreground accent bar sits slightly in front for depth.
// 2) LIGHT RIG: scene supplies ambient 0.6 + key 1.2. Locally we add a warm
//    fill point (0.6) and a red-hued rim spot (1.0) behind/above the card so
//    the machined header strip and CTA edges catch light without blowout.
// 3) MATERIALS: card body + header = MeshPhysicalNodeMaterial (roughness .55,
//    metalness .5, clearcoat .2, faux anisotropic sweep on header). CTA =
//    MeshPhysicalNodeMaterial w/ TSL vertical gradient colorNode + emissive
//    perimeter glow node. Hairlines/backdrop = MeshBasicNodeMaterial (flat,
//    non-hero, do not carry lighting responsibility).
// 4) MOTION: weighted-settle scale 1.04->1.0 (900ms, power4-ish overshoot) on
//    mount; feature rows stagger fade-up (80ms stagger, 500ms); header
//    specular band sweeps once during settle; CTA press-down 0.97 on
//    pointerdown/up. All timelines tracked + killed in cleanup().
// 5) FOCAL ELEMENT: the "$480" price figure — brightest text (near-white),
//    largest scale; everything else graded below it; ONE red accent lives
//    only on the CTA row + thin foreground accent bar (<=10% of frame).
// =============================================================================

import {
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  color,
  mix,
  smoothstep,
  uniform,
  min as tslMin,
  abs as tslAbs,
  float,
  vec3,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, SpotLight, PointLight, Color } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#ff4450' }, { at: 1, hex: '#c1121f' }],
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role) => items.filter((i) => i.role === role);
  const tierNameItem = byRole('tier-name')[0] ?? { text: 'ATELIER RESERVE' };
  const priceItem = byRole('price')[0] ?? { text: '$480' };
  const captionItem = byRole('caption')[0] ?? { text: 'PER MONTH, BILLED ANNUALLY' };
  const featureItems = byRole('feature');
  const ctaItem = byRole('cta-label')[0] ?? { text: 'JOIN THE RESERVE' };

  const root = new Group();
  root.name = 'premium-pricing-card';

  const timelines = [];
  const disposables = { geometries: [], materials: [], lights: [] };

  // ---------------------------------------------------------------------
  // BACKDROP — stage plane, ~7x6 at z=-2.5, graded dark (never flat void)
  // color.background / color.surface / color.gradient
  // ---------------------------------------------------------------------
  function buildBackdrop() {
    const geo = new PlaneGeometry(7, 6);
    const mat = new MeshBasicNodeMaterial();
    const top = color(colors.background);
    const bottom = color(colors.surface);
    const vGrad = mix(top, bottom, uv().y);

    const stops = colors.gradientStops ?? [{ at: 0, hex: '#ff4450' }, { at: 1, hex: '#c1121f' }];
    const glowA = color(stops[0].hex);
    const glowB = color(stops[stops.length - 1].hex);
    const centered = uv().sub(vec3(0.5, 0.42, 0).xy);
    const dist = centered.length();
    const glowMask = smoothstep(0.55, 0.05, dist).mul(0.14);
    const glowColor = mix(glowA, glowB, uv().y);

    mat.colorNode = vGrad.add(glowColor.mul(glowMask));

    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, 0, -2.5);
    root.add(mesh);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    return mesh;
  }

  // ---------------------------------------------------------------------
  // CARD BODY — 2.4 x 3.2 slab, albedo #16161d, hairline border #2a2a33
  // effects.spec / color.surface / color.ink
  // ---------------------------------------------------------------------
  function buildCardBody(cardGroup) {
    const borderGeo = new BoxGeometry(2.406, 3.206, 0.078);
    const borderMat = new MeshPhysicalNodeMaterial({
      color: new Color('#2a2a33'),
      roughness: 0.6,
      metalness: 0.3,
    });
    const borderMesh = new Mesh(borderGeo, borderMat);
    borderMesh.position.z = -0.001;
    cardGroup.add(borderMesh);

    const bodyGeo = new BoxGeometry(2.4, 3.2, 0.08);
    const bodyMat = new MeshPhysicalNodeMaterial({
      color: new Color(colors.surface),
      roughness: 0.55,
      metalness: 0.45,
      clearcoat: 0.2,
      clearcoatRoughness: 0.35,
    });
    const bodyMesh = new Mesh(bodyGeo, bodyMat);
    cardGroup.add(bodyMesh);

    disposables.geometries.push(borderGeo, bodyGeo);
    disposables.materials.push(borderMat, bodyMat);
    return bodyMesh;
  }

  // ---------------------------------------------------------------------
  // HEADER STRIP — machined metal, brushed anisotropy, sweeping specular
  // effects.spec (header strip)
  // ---------------------------------------------------------------------
  function buildHeaderStrip(cardGroup) {
    const geo = new BoxGeometry(2.4, 0.08, 0.09);
    const mat = new MeshPhysicalNodeMaterial({
      color: new Color(colors.surface),
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
      clearcoatRoughness: 0.3,
    });
    mat.anisotropy = 0.6;
    mat.anisotropyRotation = 0.0;

    const bandPos = uniform(-0.4);
    const uvx = uv().x;
    const band = smoothstep(0.0, 0.12, float(1.0).sub(tslAbs(uvx.sub(bandPos))));
    const base = color(colors.surface);
    mat.colorNode = mix(base, vec3(1.0, 0.97, 0.94), band.mul(0.55));

    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, 1.56, 0.005);
    cardGroup.add(mesh);

    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    return { mesh, bandPos };
  }

  // ---------------------------------------------------------------------
  // HAIRLINES — thin dividers #23232b between feature rows
  // effects.spec (interior rhythm)
  // ---------------------------------------------------------------------
  function buildHairline(cardGroup, y) {
    const geo = new PlaneGeometry(1.4, 0.006);
    const mat = new MeshBasicNodeMaterial({ color: new Color('#23232b') });
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, y, 0.045);
    cardGroup.add(mesh);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    return mesh;
  }

  // ---------------------------------------------------------------------
  // TEXT — tier-name / price+caption / features / cta-label via ctx.fontAtlas
  // text.tier-name.0, text.price.1, text.caption.2, text.feature.3-6,
  // text.cta-label.7
  // ---------------------------------------------------------------------
  function buildText(cardGroup) {
    const tierNameNode = ctx.fontAtlas.createText(tierNameItem.text, {
      fontSize: 20,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 1.6,
    });
    tierNameNode.position.set(-1.4, 1.18, 0.05);
    cardGroup.add(tierNameNode);

    const priceNode = ctx.fontAtlas.createText(priceItem.text, {
      fontSize: 62,
      color: '#ffffff',
      align: 'left',
    });
    priceNode.position.set(-1.4, 0.68, 0.05);
    cardGroup.add(priceNode);

    const captionNode = ctx.fontAtlas.createText(captionItem.text, {
      fontSize: 9,
      color: '#9aa0ab',
      align: 'left',
      letterSpacingPx: 1.1,
    });
    captionNode.position.set(-1.4, 0.42, 0.05);
    cardGroup.add(captionNode);

    const featureNodes = [];
    const rowHeight = 0.375;
    const featuresStartY = 0.02;
    featureItems.forEach((item, i) => {
      const y = featuresStartY - i * rowHeight;
      const t = ctx.fontAtlas.createText(item.text, {
        fontSize: 13,
        color: '#c9ccd3',
        align: 'left',
      });
      t.position.set(-1.4, y, 0.05);
      cardGroup.add(t);
      featureNodes.push(t);
      if (i < featureItems.length - 1) {
        buildHairline(cardGroup, y - rowHeight / 2);
      }
    });

    return { tierNameNode, priceNode, captionNode, featureNodes };
  }

  // ---------------------------------------------------------------------
  // CTA — 1.4 x 0.36 button, engineered vertical gradient + emissive rim
  // effects.spec (CTA row), text.cta-label.7, color.accent, color.gradient
  // ---------------------------------------------------------------------
  function buildCTA(cardGroup) {
    const geo = new BoxGeometry(1.4, 0.36, 0.05);
    const mat = new MeshPhysicalNodeMaterial({
      roughness: 0.5,
      metalness: 0.2,
      clearcoat: 0.15,
    });

    const stops = colors.gradientStops ?? [{ hex: '#ff4450' }, { hex: '#c1121f' }];
    const gTop = color(stops[0].hex);
    const gBottom = color(stops[stops.length - 1].hex);
    const grad = mix(gTop, gBottom, uv().y);
    mat.colorNode = grad;

    const edgeX = tslMin(uv().x, float(1.0).sub(uv().x));
    const edgeY = tslMin(uv().y, float(1.0).sub(uv().y));
    const edge = tslMin(edgeX, edgeY);
    const rim = smoothstep(0.06, 0.0, edge);
    mat.emissiveNode = color(colors.accent).mul(rim).mul(1.5);
    mat.emissive = new Color(colors.accent);

    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, -0.92, 0.06);
    cardGroup.add(mesh);

    const label = ctx.fontAtlas.createText(ctaItem.text, {
      fontSize: 13,
      color: colors.ink,
      align: 'center',
      letterSpacingPx: 1.0,
    });
    label.position.set(0, -0.94, 0.09);
    cardGroup.add(label);

    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    return { mesh, label };
  }

  // ---------------------------------------------------------------------
  // FOREGROUND ACCENT BAR — third depth plane, thin red accent (<=10% frame)
  // color.accent
  // ---------------------------------------------------------------------
  function buildForegroundAccent() {
    const geo = new BoxGeometry(0.02, 3.2, 0.02);
    const mat = new MeshPhysicalNodeMaterial({
      color: new Color(colors.accent),
      roughness: 0.4,
      metalness: 0.1,
    });
    mat.emissiveNode = color(colors.accent).mul(0.5);
    mat.emissive = new Color(colors.accent);
    const mesh = new Mesh(geo, mat);
    mesh.position.set(-1.55, 0, 0.4);
    root.add(mesh);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    return mesh;
  }

  // ---------------------------------------------------------------------
  // LIGHTS — node-local rim + fill (scene supplies ambient 0.6 + key 1.2)
  // ---------------------------------------------------------------------
  function buildLights(cardGroup) {
    const fill = new PointLight(new Color('#d8dde6'), 0.6, 8, 2);
    fill.position.set(-2.2, 1.0, 2.2);
    cardGroup.add(fill);

    const rim = new SpotLight(new Color(colors.accent), 1.0, 6, 0.6, 0.5);
    rim.position.set(-1.3, 2.0, -1.6);
    rim.target.position.set(0, 0.4, 0);
    cardGroup.add(rim);
    cardGroup.add(rim.target);

    disposables.lights.push(fill, rim);
    return { fill, rim };
  }

  // ---------------------------------------------------------------------
  // MOTION — weighted-settle mount, header sweep, feature stagger fade-up
  // ---------------------------------------------------------------------
  function setOpacity(node, value) {
    node.traverse((child) => {
      if (child.material) {
        child.material.transparent = true;
        if ('opacity' in child.material) child.material.opacity = value;
      }
    });
  }

  function buildMotion(cardGroup, headerRef, textRefs, cta) {
    cardGroup.scale.set(0.001, 0.001, 0.001);
    const settleTl = gsap.timeline();
    settleTl.to(cardGroup.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.55,
      ease: 'power3.out',
    }).to(cardGroup.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.35,
      ease: 'power4.out',
    });
    settleTl.to(headerRef.bandPos, {
      value: 1.4,
      duration: 0.9,
      ease: 'power2.out',
      onUpdate: () => {
        headerRef.bandPos.value = headerRef.bandPos.value;
      },
    }, 0);
    timelines.push(settleTl);

    const rows = [...textRefs.featureNodes];
    rows.forEach((r, i) => {
      const baseY = r.position.y;
      r.position.y = baseY + 0.2;
      setOpacity(r, 0);
    });
    const staggerTl = gsap.timeline({ delay: 0.15 });
    rows.forEach((r, i) => {
      const baseY = r.position.y - 0.2;
      staggerTl.to(r.position, {
        y: baseY,
        duration: 0.5,
        ease: 'power2.out',
      }, i * 0.08);
      staggerTl.to({ v: 0 }, {
        v: 1,
        duration: 0.5,
        ease: 'power2.out',
        onUpdate: function () {
          setOpacity(r, this.targets()[0].v);
        },
      }, i * 0.08);
    });
    timelines.push(staggerTl);

    return { settleTl, staggerTl };
  }

  function attachCTAHandlers(cardGroup, cta) {
    let pressTl = null;
    root.userData.handlers = root.userData.handlers ?? {};
    root.userData.handlers.onPointerDown = () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.to(cta.mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
      });
      timelines.push(pressTl);
    };
    root.userData.handlers.onPointerUp = () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.to(cta.mesh.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.18,
        ease: 'power2.out',
      });
      timelines.push(pressTl);
    };
    root.userData.handlers.onClick = () => {
      ctx.emit?.('navigate', { to: 'hub-pricing' });
    };
  }

  // ---------------------------------------------------------------------
  // ASSEMBLE
  // ---------------------------------------------------------------------
  buildBackdrop();

  const cardGroup = new Group();
  cardGroup.name = 'pricing-card-slab';
  root.add(cardGroup);

  buildCardBody(cardGroup);
  const headerRef = buildHeaderStrip(cardGroup);
  const textRefs = buildText(cardGroup);
  const cta = buildCTA(cardGroup);
  buildForegroundAccent();
  buildLights(cardGroup);
  buildMotion(cardGroup, headerRef, textRefs, cta);
  attachCTAHandlers(cardGroup, cta);

  // ---------------------------------------------------------------------
  // PRIMITIVES — none listed in config.cinematicPrimitives for this node
  // ---------------------------------------------------------------------
  const appliedPrimitives = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    if (ctx.primitives?.[prim.name]) {
      const result = ctx.primitives[prim.name](cardGroup, prim.params ?? {});
      appliedPrimitives.push(result);
    }
  }

  // ---------------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    appliedPrimitives.forEach((p) => p?.cleanup?.());
    disposables.geometries.forEach((g) => g.dispose());
    disposables.materials.forEach((m) => m.dispose());
    disposables.lights.forEach((l) => {
      l.dispose?.();
      l.target?.parent?.remove(l.target);
    });
    root.traverse((child) => {
      if (child.geometry && !disposables.geometries.includes(child.geometry)) {
        child.geometry.dispose?.();
      }
      if (child.material && !disposables.materials.includes(child.material)) {
        child.material.dispose?.();
      }
    });
  };

  return root;
}

